// 检测添加边后是否会形成环（从起点出发DFS模拟）
function hasCycle(nodes, edges, start, end) {
  // 复制当前邻接表
  const adj = new Map();
  nodes.forEach(n => adj.set(n.id, []));
  edges.forEach(([from, to]) => adj.get(from).push(to));
  // 加入待添加边
  adj.get(start).push(end);

  // 状态：0=未访问，1=访问中，2=已访问完成
  const state = new Map();
  nodes.forEach(n => state.set(n.id, 0));

  function dfs(node) {
    state.set(node, 1);
    const neighbors = adj.get(node) || [];
    for (const next of neighbors) {
      if (state.get(next) === 1) return true; // 回边 = 有环
      if (state.get(next) === 0 && dfs(next)) return true;
    }
    state.set(node, 2);
    return false;
  }

  for (const n of nodes) {
    if (state.get(n.id) === 0) {
      if (dfs(n.id)) return true;
    }
  }
  return false;
}
